import importlib.util,json,sys
from pathlib import Path
s=importlib.util.spec_from_file_location('gateway','/workspace/shawu/concepts_v4/_work/edit_api.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
r=Path('/workspace/shawu/m3-work');m.OUT=r/'art';m.WORK=r/'art';name=sys.argv[1]
prompts={
'disciples':'''Use case: style-transfer. Produce one premium hand-painted HD 2D JRPG BACKGROUND ONLY. Image 1 is the exact actor-free game background composition, a 160x144 viewport enlarged 3x. Preserve its exact 10:9 aspect and all geometry: blue sky with a few small white clouds, pale floating stone courtyard with cracked paving, stepped asymmetrical blue-white ornamental railings, red inset panels, and a large golden ritual incense vessel on the LEFT. Keep every corner, terrace boundary, stairs and object at precisely the reference normalized coordinates. Camera is high-angle top-down. Image 2 is only approved painterly material and lighting guidance. Zero people, characters, animals, creatures, faces, figures, portraits, shadows of characters, writing, text, logos, dialogue boxes, UI or extra objects. The pale grey empty area outside architectural terraces in image 1 belongs to the original background and must remain in the same position. Fine hand-painted stone and metal detail, readable scale, no grid lines. Output one finished 10:9 background, no margins, no montage. Do not alter composition.''',
'dialogue':'''Use case: style-transfer. Produce a reusable premium HD 2D JRPG dialogue-frame asset. Image 1 is the precise layout reference: a wide rectangular Chinese game dialogue frame, 160:64 aspect, narrow red-and-gold ornamental outer edge, pale ivory interior. Keep its exact proportions. Refine ONLY the border into carefully painted carved red lacquer, thin warm gold filigree, restrained Chinese cloud-pattern corner details. Border must remain very narrow, around 3 original pixels out of 160 width, so text area is maximized. Uniform flat pale ivory interior, no embellishments inside. ZERO text, calligraphy, glyphs, numbers, icons, arrows, portraits, characters, faces, creatures or backgrounds. Image 2 is painterly material guidance only; no subjects from it. Output exactly one complete flat rectangular frame, straight-on, no perspective, no mockup, no surrounding margins. This will be nine-slice cropped, so four corners and uninterrupted straight edges are required.'''}
m.FILES[name]=(r/'art_requests'/f'{name}_layout.png',r/'art_requests/style.jpg');m.PROMPTS[name]=prompts[name]
(r/'art'/f'{name}_prompt.txt').write_text(prompts[name])
res=m.attempt(name,quality='medium',use_fidelity=False,tag='m3');print(json.dumps({'scene':name,'ok':res.get('ok'),'path':res.get('path')}))
